,"is_grantable":"NO","table_schema":"public","table_catalog":"postgres","privilege_type":"UPDATE","with_hierarchy":"NO"},{"grantee":"anon","grantor":"postgres","table_name":"logs_sistema","is_grantable":"NO","table_schema":"public","table_catalog":"postgres","privilege_type":"DELETE","with_hierarchy":"NO"},{"grantee":"anon","grantor":"postgres","table_name":"logs_sistema","is_grantable":"NO","table_schema":"public","table_catalog":"postgres","privilege_type":"TRUNCATE","with_hierarchy":"NO"},{"grantee":"anon","grantor":"postgres","table_name":"logs_sistema","is_grantable":"NO","table_schema":"public","table_catalog":"postgres","privilege_type":"REFERENCES","with_hierarchy":"NO"},{"grantee":"anon","grantor":"postgres","table_name":"logs_sistema","is_grantable":"NO","table_schema":"public","table_catalog":"postgres","privilege_type":"TRIGGER","with_hierarchy":"NO"},{"grantee":"authenticated","grantor":"postgres","table_name":"logs_sistema","is_grantable":"NO","table_schema":"public","table_catalog":"postgres","privilege_type":"INSERT","with_hierarchy":"NO"},{"grantee":"authenticated","grantor":"postgres","table_name":"logs_sistema","is_grantable":"NO","table_schema":"public","table_catalog":"postgres","privilege_type":"SELECT","with_hierarchy":"YES"},{"grantee":"authenticated","grantor":"postgres","table_name":"logs_sistema","is_grantable":"NO","table_schema":"public","table_catalog":"postgres","privilege_type":"UPDATE","with_hierarchy":"NO"},{"grantee":"authenticated","grantor":"postgres","table_name":"logs_sistema","is_grantable":"NO","table_schema":"public","table_catalog":"postgres","privilege_type":"DELETE","with_hierarchy":"NO"},{"grantee":"authenticated","grantor":"postgres","table_name":"logs_sistema","is_grantable":"NO","table_schema":"public","table_catalog":"postgres","privilege_type":"TRUNCATE","with_hierarchy":"NO"},{"grantee":"authenticated","grantor":"postgres","table_name":"logs_sistema","is_grantable":"NO","table_schema":"public","table_catalog":"postgres","privilege_type":"REFERENCES","with_hierarchy":"NO"},{"grantee":"authenticated","grantor":"postgres","table_name":"logs_sistema","is_grantable":"NO","table_schema":"public","table_catalog":"postgres","privilege_type":"TRIGGER","with_hierarchy":"NO"}]'::jsonb;
IF NOT(actual @> expected AND expected @> actual) OR jsonb_array_length(actual)<>jsonb_array_length(expected) THEN RAISE EXCEPTION 'Production grants changed since review. Review again.';END IF;
IF EXISTS(SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND a.attacl IS NOT NULL) THEN RAISE EXCEPTION 'Explicit column grants require separate review';END IF;
IF to_regnamespace('amr_private') IS NOT NULL THEN RAISE EXCEPTION 'Private security schema already exists; do not overwrite it';END IF;
END $snapshot_check$;
DO $amr_preflight$
DECLARE t text; invalid boolean;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.usuarios_clinica m JOIN auth.users u ON u.id=m.auth_user_id JOIN public.clinicas c ON c.id=m.clinica_id WHERE m.activo IS TRUE AND m.rol='admin' AND u.email_confirmed_at IS NOT NULL) THEN
  RAISE EXCEPTION 'No confirmed active administrator; abort before changing permissions';
 END IF;
 IF EXISTS(SELECT 1 FROM public.usuarios_clinica WHERE activo IS TRUE AND auth_user_id IS NOT NULL GROUP BY auth_user_id,clinica_id HAVING count(DISTINCT rol)>1) THEN RAISE EXCEPTION 'Conflicting membership roles; no changes applied';END IF;
 FOREACH t IN ARRAY ARRAY['pacientes','citas','historias_clinicas','consentimientos','firmas_sesiones','facturas'] LOOP
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE clinica_id IS NULL)',t) INTO invalid;
  IF invalid THEN RAISE EXCEPTION 'Null clinic IDs in %; no data will be reassigned',t;END IF;
 END LOOP;
END $amr_preflight$;
DO $amr_relations$
DECLARE t text; invalid boolean;
BEGIN
 FOREACH t IN ARRAY ARRAY['citas','historias_clinicas','consentimientos','firmas_sesiones','facturas'] LOOP
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I r LEFT JOIN public.pacientes p ON p.id=r.paciente_id WHERE r.paciente_id IS NULL OR p.id IS NULL OR r.clinica_id IS DISTINCT FROM p.clinica_id)',t) INTO invalid;
  IF invalid THEN RAISE EXCEPTION 'Invalid patient relationship in %; abort without changing data',t;END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.firmas_sesiones f LEFT JOIN public.citas c ON c.id=f.cita_id WHERE f.cita_id IS NOT NULL AND (c.id IS NULL OR f.clinica_id IS DISTINCT FROM c.clinica_id OR f.paciente_id IS DISTINCT FROM c.paciente_id)) THEN RAISE EXCEPTION 'Invalid appointment/signature relationship';END IF;
END $amr_relations$;
SELECT 'PASS: reviewed production metadata and admin access preconditions match' AS result;
ROLLBACK;
